use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub struct Matrix {
    rows: usize,
    cols: usize,
    data: Vec<f64>,
}

/// Errors that can occur when constructing or combining matrices.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ShapeError {
    /// The matrix has no rows, or a row has no columns.
    Empty,
    /// A row has a different number of columns than the first row.
    Ragged { row: usize, expected: usize, found: usize },
    /// Two matrices have incompatible shapes.
    Mismatch { left: (usize, usize), right: (usize, usize) },
}

impl fmt::Display for ShapeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ShapeError::Empty => write!(f, "empty matrix"),
            ShapeError::Ragged { row, expected, found } => {
                write!(f, "row {} has {} columns, expected {}", row, found, expected)
            }
            ShapeError::Mismatch { left, right } => {
                write!(f, "shape mismatch: {} vs {}", left.0 * left.1, right.0 * right.1)
            }
        }
    }
}

impl Matrix {
    pub fn zeros(rows: usize, cols: usize) -> Matrix {
        Matrix { rows, cols, data: vec![0.0; rows * cols] }
    }

    /// Build a matrix from rows of values.
    ///
    /// Fails with [`ShapeError::Empty`] if there are no rows or a row is
    /// empty, and with [`ShapeError::Ragged`] if rows have unequal lengths.
    pub fn from_rows(rows: Vec<Vec<f64>>) -> Result<Matrix, ShapeError> {
        if rows.is_empty() {
            return Err(ShapeError::Empty);
        }
        let cols = rows[0].len();
        if cols == 0 {
            return Err(ShapeError::Empty);
        }
        let mut data = Vec::with_capacity(rows.len() * cols);
        for (i, row) in rows.into_iter().enumerate() {
            if row.len() != cols {
                return Err(ShapeError::Ragged { row: i, expected: cols, found: row.len() });
            }
            data.extend_from_slice(&row);
        }
        Ok(Matrix { rows: data.len() / cols, cols, data })
    }

    /// The `n x n` identity matrix.
    pub fn identity(n: usize) -> Matrix {
        let mut m = Matrix::zeros(n, n);
        for i in 0..n {
            m.data[i * n + i] = 1.0;
        }
        m
    }

    pub fn rows(&self) -> usize {
        self.rows
    }

    pub fn cols(&self) -> usize {
        self.cols
    }

    pub fn get(&self, r: usize, c: usize) -> Option<f64> {
        if r < self.rows && c < self.cols {
            Some(self.data[r * self.cols + c])
        } else {
            None
        }
    }

    pub fn set(&mut self, r: usize, c: usize, v: f64) -> bool {
        if r < self.rows && c < self.cols {
            self.data[r * self.cols + c] = v;
            true
        } else {
            false
        }
    }

    /// The transpose of this matrix.
    pub fn transpose(&self) -> Matrix {
        let mut t = Matrix::zeros(self.cols, self.rows);
        for r in 0..self.rows {
            for c in 0..self.cols {
                t.data[c * self.rows + r] = self.data[r * self.cols + c];
            }
        }
        t
    }

    /// Element-wise addition. Both matrices must have the same shape.
    pub fn add(&self, other: &Matrix) -> Result<Matrix, ShapeError> {
        if (self.rows, self.cols) != (other.rows, other.cols) {
            return Err(ShapeError::Mismatch {
                left: (self.rows, self.cols),
                right: (other.rows, other.cols),
            });
        }
        let mut out = Matrix::zeros(self.rows, self.cols);
        for i in 0..self.data.len() {
            out.data[i] = self.data[i] + other.data[i];
        }
        Ok(out)
    }

    /// Matrix multiplication. `self.cols` must equal `other.rows`.
    pub fn mul(&self, other: &Matrix) -> Result<Matrix, ShapeError> {
        if self.cols != other.rows {
            return Err(ShapeError::Mismatch {
                left: (self.rows, self.cols),
                right: (other.rows, other.cols),
            });
        }
        let mut out = Matrix::zeros(self.rows, other.cols);
        for r in 0..self.rows {
            for c in 0..other.cols {
                let mut sum = 0.0;
                for k in 0..self.cols {
                    sum += self.data[r * self.cols + k] * other.data[k * other.cols + c];
                }
                out.data[r * other.cols + c] = sum;
            }
        }
        Ok(out)
    }
}

impl fmt::Display for Matrix {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut widths = vec![0; self.cols];
        for r in 0..self.rows {
            for c in 0..self.cols {
                let s = format!("{:.1}", self.data[r * self.cols + c]);
                widths[c] = widths[c].max(s.len());
            }
        }
        for r in 0..self.rows {
            write!(f, "[")?;
            for c in 0..self.cols {
                let s = format!("{:.1}", self.data[r * self.cols + c]);
                if c > 0 {
                    write!(f, " ")?;
                }
                write!(f, "{:>width$}", s, width = widths[c])?;
            }
            write!(f, "]")?;
            if r + 1 < self.rows {
                writeln!(f)?;
            }
        }
        Ok(())
    }
}
